if (points.empty()) {
    return BBox3d();
}
BBox3d bb;
bb.min() = points[0];
bb.max() = points[0];
for (const cg3::Point3d& p : points) {
    bb.min() = bb.min().min(p);
    bb.max() = bb.max().max(p);
}
return bb;

